bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
docker inspect "$name" >/dev/null 2>&1 || exit 61
if test "$(docker inspect -f '{{.State.Running}}' "$name")" = true &&
 docker logs --tail 100 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$';then
 echo STK04_DM_READY=PASS
 exit 0
fi
image="$(docker inspect -f '{{.Image}}' "$name")"
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
dbpass="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}' "$name")"
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test -f "$token" && test -f "$dbpass" && test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || exit 62
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || exit 63
docker run --rm -i --network "$net" --pull never --cap-drop ALL \
 -e NODE_ENV=production -e VIDEOBOT_RUN_MODE=telegram_poll \
 -e VIDEOBOT_PRIVATE_INGRESS_ONLY=true -e VIDEOBOT_SCHEMA_MIGRATE=YES \
 -e VIDEOBOT_TELEGRAM_TOKEN_FILE=/run/secrets/videobot_telegram_token \
 -e VIDEOBOT_DB_PASSWORD_FILE=/run/secrets/videobot_db_password \
 -e VIDEOBOT_DB_HOST=deploy-postgres-1 -e VIDEOBOT_DB_NAME=videobot \
 -e VIDEOBOT_DB_USER="$user" \
 --mount "type=bind,source=$token,target=/run/secrets/videobot_telegram_token,readonly" \
 --mount "type=bind,source=$dbpass,target=/run/secrets/videobot_db_password,readonly" \
 --entrypoint node "$image" --input-type=module <<'JS'
import {statSync} from 'node:fs';
import {createCreatorPollingRuntime} from './src/runtime/creatorPollingMain.mjs';
const stat=statSync(process.env.VIDEOBOT_DB_PASSWORD_FILE);
if(!stat.isFile())process.exit(70);
if((stat.mode&0o077)!==0)process.exit(71);
if(stat.size<12)process.exit(72);
if(stat.size>4096)process.exit(73);
if(stat.uid!==process.getuid())process.exit(74);
try {
 const rt=await createCreatorPollingRuntime();
 await rt.close();
 console.log('STK04_CREATOR_RUNTIME_CONSTRUCT=PASS');
} catch(e) {
 const c=String(e?.code??''),m=String(e?.message??'');
 if(m==='CREATOR_POLL_DB_PASSWORD_FILE_INVALID')process.exitCode=80;
 else if(m==='CREATOR_POLL_INTERNAL_DB_CONFIG_INVALID')process.exitCode=81;
 else if(m==='CREATOR_POLL_PRIVATE_MODE_REQUIRED')process.exitCode=82;
 else if(m==='CREATOR_POLL_PRIVATE_DB_SECRET_REQUIRED')process.exitCode=83;
 else if(m==='CREATOR_POLL_PRIVATE_SECRET_MOUNT_REQUIRED')process.exitCode=84;
 else if(m==='CREATOR_POLL_SCHEMA_OWNER_CONSENT_MISSING')process.exitCode=85;
 else if(m==='CREATOR_POLL_EXISTING_WEBHOOK_MUST_NOT_BE_REPLACED')process.exitCode=86;
 else if(c==='28P01'||c==='3D000'||c==='42501')process.exitCode=87;
 else if(c==='ECONNREFUSED'||c==='ENOTFOUND'||c==='ETIMEDOUT')process.exitCode=88;
 else if(c==='ERR_MODULE_NOT_FOUND')process.exitCode=89;
 else if(/VideoBot migration|schema|SQL/i.test(m))process.exitCode=90;
 else if(/TG_|identity|token|bot/i.test(m))process.exitCode=91;
 else process.exitCode=92;
}
JS
